import random
import struct
from typing import List

# Data type: arbitrary binary data
# Target stubs expect buffers consumed by endian readers and opaque consumers.
# Strategy:
# - Produce a mix of sizes with at least 4 bytes often (to satisfy DWORD readers),
#   but also occasionally smaller buffers (>=2) to vary coverage for WORD readers.
# - Fill with patterns that are interesting for endian decoders and compressors:
#   * Repeating sequences (00, FF, 7F, 80) to hit boundaries
#   * Incrementing/decrementing ramps
#   * Alternating bit patterns (AA, 55)
#   * Embedded multi-byte values at random offsets (known LE/BE words/dwords)
# - Keep size <= 4096 bytes.

_MAX_SIZE = 4096

_DEF_PATTERNS: List[bytes] = [
    bytes([0x00]),
    bytes([0xFF]),
    bytes([0x7F]),
    bytes([0x80]),
    bytes([0xAA]),
    bytes([0x55]),
]

# Some interesting 16-bit values
_WORDS = [0x0000, 0x0001, 0x00FF, 0xFF00, 0x7FFF, 0x8000, 0xFFFF, 0x1234, 0xBEEF]
# Some interesting 32-bit values
_DWORDS = [0x00000000, 0x00000001, 0x7FFFFFFF, 0x80000000, 0xFFFFFFFF, 0x11223344, 0xA5A5A5A5, 0x5A5A5A5A]


def _rand_size(rng: random.Random) -> int:
    # Bias toward 2048 (XModule::IdentificationBufferSize) and small sizes >= 2
    choices = [
        (2, 5), (3, 2), (4, 10), (8, 5), (16, 5), (32, 5), (64, 5), (128, 5),
        (256, 5), (512, 5), (1024, 5), (2048, 12), (3072, 3)
    ]
    population = []
    for sz, w in choices:
        population.extend([sz] * w)
    population.append(rng.randint(2, min(1024, _MAX_SIZE)))
    sz = rng.choice(population)
    # Occasionally choose a random size up to 4096
    if rng.random() < 0.2:
        sz = rng.randint(2, _MAX_SIZE)
    return max(2, min(_MAX_SIZE, sz))


def _ramp_bytes(length: int, rng: random.Random, descending: bool = False) -> bytes:
    start = rng.randint(0, 255)
    step = rng.choice([1, 3, 5, 7, 13])
    data = bytearray(length)
    val = start
    for i in range(length):
        data[i] = val & 0xFF
        val = (val - step) & 0xFF if descending else (val + step) & 0xFF
    return bytes(data)


def _alt_pattern(length: int, b0: int, b1: int) -> bytes:
    return bytes((b0 if (i & 1) == 0 else b1) for i in range(length))


def _repeat_pattern(length: int, pat: bytes) -> bytes:
    if not pat:
        return bytes(length)
    reps, rem = divmod(length, len(pat))
    return pat * reps + pat[:rem]


def _embed_values(buf: bytearray, rng: random.Random) -> None:
    n = len(buf)
    # Decide how many embeddings
    num_words = rng.randint(1, max(1, n // 64))
    num_dwords = rng.randint(1, max(1, n // 128))

    # Embed 16-bit values in both LE and BE at random offsets that fit
    for _ in range(num_words):
        if n < 2:
            break
        off = rng.randint(0, n - 2)
        val = rng.choice(_WORDS)
        if rng.random() < 0.5:
            enc = struct.pack('<H', val)
        else:
            enc = struct.pack('>H', val)
        buf[off:off + 2] = enc

    # Embed 32-bit values in both LE and BE at random offsets that fit
    for _ in range(num_dwords):
        if n < 4:
            break
        off = rng.randint(0, n - 4)
        val = rng.choice(_DWORDS)
        if rng.random() < 0.5:
            enc = struct.pack('<I', val)
        else:
            enc = struct.pack('>I', val)
        buf[off:off + 4] = enc

    # Ensure at least one LE and one BE dword near start if possible
    if n >= 8:
        le = struct.pack('<I', rng.choice(_DWORDS))
        be = struct.pack('>I', rng.choice(_DWORDS))
        buf[0:4] = le
        buf[4:8] = be


def _make_base(length: int, rng: random.Random) -> bytes:
    # Choose a base fill strategy
    strategy = rng.choices(
        population=['repeat', 'alt', 'ramp_up', 'ramp_down', 'random'],
        weights=[3, 2, 2, 2, 3],
        k=1
    )[0]

    if strategy == 'repeat':
        pat = rng.choice(_DEF_PATTERNS)
        return _repeat_pattern(length, pat)
    elif strategy == 'alt':
        pairs = [(0x00, 0xFF), (0xAA, 0x55), (0x7F, 0x80), (0x00, 0x00), (0xFF, 0xFF)]
        b0, b1 = rng.choice(pairs)
        return _alt_pattern(length, b0, b1)
    elif strategy == 'ramp_up':
        return _ramp_bytes(length, rng, descending=False)
    elif strategy == 'ramp_down':
        return _ramp_bytes(length, rng, descending=True)
    else:
        # random bytes, but with slight bias to common values
        data = bytearray(length)
        for i in range(length):
            r = rng.random()
            if r < 0.15:
                data[i] = 0x00
            elif r < 0.30:
                data[i] = 0xFF
            elif r < 0.45:
                data[i] = 0x80
            elif r < 0.60:
                data[i] = 0x7F
            else:
                data[i] = rng.randrange(256)
        return bytes(data)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    size = _rand_size(rng)
    # Ensure at least 4 bytes most of the time, but allow 2+ sometimes to still be valid
    if size < 4 and rng.random() < 0.75:
        size = 4

    base = bytearray(_make_base(size, rng))

    # Optionally splice in another pattern block to increase variety
    if size > 16 and rng.random() < 0.6:
        block_len = rng.randint(4, min(128, size // 2))
        start = rng.randint(0, size - block_len)
        block = _make_base(block_len, rng)
        base[start:start + block_len] = block

    # Embed interesting LE/BE words/dwords at random offsets
    _embed_values(base, rng)

    # Occasionally pad or resize to exactly 2048 bytes to satisfy identifyModule consumers
    if rng.random() < 0.4:
        # If shorter than 2048, pad with zeros; if longer, truncate
        target = 2048
        if target <= _MAX_SIZE:
            if len(base) < target:
                base.extend(b"\x00" * (target - len(base)))
            elif len(base) > target:
                del base[target:]

    # Cap to max size just in case
    if len(base) > _MAX_SIZE:
        del base[_MAX_SIZE:]

    return bytes(base)
